class FenwickTree {
    constructor(n) {
        this.val = new Array(n + 1).fill(0);
    }
    add(x, v) {
        while (x < this.val.length) {
            this.val[x] += v;
            x += x & (~x + 1);
        }
    }
    sum(x) {
        if (!(x < this.val.length)) {
            throw new Error("assertion failed");
        }
        let ans = 0;
        while (x > 0) {
            ans += this.val[x];
            x -= x & (~x + 1);
        }
        return ans;
    }
}

function sieve(n) {
    const is_prime = new Array(n + 1).fill(true);
    for (let i = 2; ; i++) {
        if (i * i > n) {
            break;
        }
        if (is_prime[i]) {
            let j = i * i;
            while (j <= n) {
                is_prime[j] = false;
                j += i;
            }
        }
    }
    const prime = [];
    for (let i = 2; i <= n; i++) {
        if (is_prime[i]) {
            prime.push(BigInt(i));
        }
    }
    return prime;
}

class PrimeCountSolver {
    constructor() {
        this.query = [];
        this.memo = [];
