        for (const v of this.query) {
            let k = (() => {
                let left = 0, right = p.length;
                while (left < right) {
                    const mid = (left + right) >> 1;
                    const val = p[mid] * p[mid];
                    if (val === v) return mid + 1;
                    if (val < v) left = mid + 1;
                    else right = mid;
                }
                return left;
            })();
            stack.push([v, k]);
