        let query = [];
        while (stack.length > 0) {
            const [n2, k] = stack.pop();
            if (k === 0) continue;
            const q = p[k - 1];
            if (q * q > n2) {
                let x = (() => {
                    let left = 0, right = k;
                    while (left < right) {
                        const mid = (left + right) >> 1;
                        const val = p[mid] * p[mid];
                        if (val === n2) return mid + 1;
                        if (val < n2) left = mid + 1;
                        else right = mid;
                    }
                    return left;
                })();
                stack.push([n2, x]);
            } else if (n2 <= bound) {
                query.push([k, n2]);
            } else {
                stack.push([n2, k - 1]);
                stack.push([n2 / q, k - 1]);
            }
        }
        query.sort((a, b) => a[0] - b[0] || (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
        query = query.filter((v, i, arr) => i === 0 || v[0] !== arr[i - 1][0] || v[1] !== arr[i - 1][1]);
        const mInt = Number(bound);
        const bit = new FenwickTree(mInt);
        for (let i = 1; i <= mInt; i++) {
            bit.add(i, 1);
        }
